CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, role ENUM('customer','admin') NOT NULL DEFAULT 'customer', status ENUM('active','blocked') NOT NULL DEFAULT 'active', failed_attempts SMALLINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS addresses (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, recipient VARCHAR(120) NOT NULL, line1 VARCHAR(180) NOT NULL, line2 VARCHAR(180), neighborhood VARCHAR(120), city VARCHAR(120) NOT NULL, state CHAR(3) NOT NULL, postal_code CHAR(5) NOT NULL, references_text VARCHAR(500), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sinaloa_postal_codes (postal_code CHAR(5) PRIMARY KEY, municipality VARCHAR(120) NOT NULL, locality VARCHAR(120) NOT NULL DEFAULT '', serviceable BOOLEAN NOT NULL DEFAULT TRUE, base_shipping_rate DECIMAL(10,2) NOT NULL DEFAULT 89.00, source VARCHAR(255) NOT NULL DEFAULT 'SEPOMEX / Correos de México', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(160) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, description TEXT, category ENUM('pijama','mameluco','ropa_diaria') NOT NULL, composition VARCHAR(120) NOT NULL DEFAULT '100% algodón', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_images (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, product_id BIGINT UNSIGNED NOT NULL, image_url VARCHAR(1000) NOT NULL, position SMALLINT NOT NULL, alt_text VARCHAR(200), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, UNIQUE(product_id,position)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_variants (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, product_id BIGINT UNSIGNED NOT NULL, sku VARCHAR(80) NOT NULL UNIQUE, size ENUM('0-3','3-6','6-12') NOT NULL, color VARCHAR(40) NOT NULL, price DECIMAL(10,2) NOT NULL, weight_grams INT UNSIGNED NOT NULL, stock INT UNSIGNED NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(product_id) REFERENCES products(id), UNIQUE(product_id,size,color), CHECK(price >= 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS carts (id CHAR(36) PRIMARY KEY, user_id BIGINT UNSIGNED NULL, status ENUM('open','converted','abandoned') NOT NULL DEFAULT 'open', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cart_items (cart_id CHAR(36) NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, PRIMARY KEY(cart_id,variant_id), FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(variant_id) REFERENCES product_variants(id), CHECK(quantity > 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS gift_options (order_id BIGINT UNSIGNED PRIMARY KEY, hide_price BOOLEAN NOT NULL DEFAULT FALSE, gift_wrap BOOLEAN NOT NULL DEFAULT FALSE, gift_note VARCHAR(500), gift_fee DECIMAL(10,2) NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, public_id CHAR(36) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, address_id BIGINT UNSIGNED NOT NULL, status ENUM('pending_payment','paid','preparing','shipped','delivered','cancelled','refunded') NOT NULL, subtotal DECIMAL(10,2) NOT NULL, shipping_fee DECIMAL(10,2) NOT NULL, total DECIMAL(10,2) NOT NULL, shipping_quote_id VARCHAR(120), carrier VARCHAR(80), tracking_number VARCHAR(120), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(address_id) REFERENCES addresses(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS order_items (order_id BIGINT UNSIGNED NOT NULL, variant_id BIGINT UNSIGNED NOT NULL, product_name VARCHAR(160) NOT NULL, size VARCHAR(8) NOT NULL, color VARCHAR(20) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(10,2) NOT NULL, PRIMARY KEY(order_id,variant_id), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNSIGNED NOT NULL, provider VARCHAR(80) NOT NULL, provider_reference VARCHAR(190), amount DECIMAL(10,2) NOT NULL, status ENUM('pending','authorized','captured','failed','refunded') NOT NULL, token_reference VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), UNIQUE(provider,provider_reference)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shipments (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNSIGNED NOT NULL UNIQUE, carrier VARCHAR(80), quote_reference VARCHAR(120), tracking_number VARCHAR(120), status ENUM('quoted','label_pending','shipped','delivered','failed') NOT NULL DEFAULT 'quoted', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shipping_quotes (id CHAR(36) PRIMARY KEY, postal_code CHAR(5) NOT NULL, state CHAR(3) NOT NULL, weight_grams INT UNSIGNED NOT NULL, amount DECIMAL(10,2) NOT NULL, provider VARCHAR(80) NOT NULL, expires_at DATETIME NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS reviews (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, product_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, rating TINYINT UNSIGNED NOT NULL, comment VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(user_id) REFERENCES users(id), CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS returns (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, reason VARCHAR(500) NOT NULL, status ENUM('requested','approved','rejected','received','refunded') NOT NULL DEFAULT 'requested', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sinaloa_postal_codes (postal_code CHAR(5) PRIMARY KEY, municipality VARCHAR(120) NOT NULL, locality VARCHAR(120) NOT NULL DEFAULT '', serviceable BOOLEAN NOT NULL DEFAULT TRUE, base_shipping_rate DECIMAL(10,2) NOT NULL DEFAULT 89.00, source VARCHAR(255) NOT NULL DEFAULT 'SEPOMEX / Correos de México', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;


CREATE TABLE IF NOT EXISTS parcel_simulations (
 shipment_id BIGINT UNSIGNED PRIMARY KEY,
 tracking_number VARCHAR(120) NOT NULL UNIQUE,
 stage ENUM('label_pending','shipped','delivered') NOT NULL,
 validation_status ENUM('pendiente','validada','rechazada') NOT NULL DEFAULT 'pendiente',
 delivered_at DATETIME NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(shipment_id) REFERENCES shipments(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS parcel_simulation_events (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
 shipment_id BIGINT UNSIGNED NOT NULL,
 stage VARCHAR(30) NOT NULL,
 event_label VARCHAR(120) NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(shipment_id) REFERENCES shipments(id),
 INDEX(shipment_id,id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS session_revocations (email VARCHAR(190) PRIMARY KEY,revoked_before BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB;
